import collections,csv,importlib.util,json,random,subprocess,tempfile,pathlib
module=importlib.util.spec_from_file_location('driver','/app/driver.py'); d=importlib.util.module_from_spec(module); module.loader.exec_module(d)
rows=[json.loads(x) for x in open('/tmp/pd440-decode.jsonl')]
bus=d.read_bus('/app/captures/site_a/bus.csv')
assert len(rows)==len(bus)==236
for row,(t,cs,op,addr,data) in zip(rows,bus):
 assert (row['t_us'],row['cs'],row['op'],row['addr'])==(t,cs,op,addr)
 assert row['revision']==('C' if cs in (0,2) else 'D')
 if addr==9: assert row['fields']==({'C_GAIN':5} if row['revision']=='C' else {'C_GAIN':10,'D_GAIN':5})
 if addr==12 and row['revision']=='D': assert row['fields']=={}
assert d.fields('C',0,0x535A)=={'PART_ID':5,'REV':3,'DIE_TRIM':90}
assert d.fields('D',1,0xA53C)=={'FAULT':165,'SEQ_STATE':60}
for revision in ('C','D'):
 assert d.fields(revision,15,65535)=={'SCRATCH':65535}
 for addr in range(16,256): assert d.fields(revision,addr,65535)=={}
rng=random.Random(440)
for rev in ('C','D'):
 for iteration in range(200):
  spec={'revision':rev,'cs':rng.randrange(100),'freq_hz':dict(zip('ABCD',[rng.randrange(256) for _ in range(4)])), 'gain':dict(zip('ABCD',[rng.randrange(64) for _ in range(4)])), 'phase_deg':dict(zip('ABCD',[2*rng.randrange(256) for _ in range(4)])), 'enable':dict(zip('ABCD',[rng.randrange(2) for _ in range(4)]))}
  writes=d.compile_excitation(spec)['writes']; registers=[0]*16
  assert writes[0]==[spec['cs'],14,0] and writes[-1][1]==14
  for cs,addr,data in writes:
   assert cs==spec['cs'] and 2<=addr<=14 and 0<=data<=65535
   assert not(rev=='D' and addr==12)
   registers[addr]=data
  for i,ch in enumerate('ABCD'):
   assert registers[2+3*i]&255==spec['freq_hz'][ch]
   assert 2*(registers[4+3*i]&255)==spec['phase_deg'][ch]
   assert (registers[14]>>i)&1==spec['enable'][ch]
   gain=(registers[9]>>(8 if i==2 else 0))&255 if rev=='D' and i>=2 else registers[3+3*i]&255
   assert gain==spec['gain'][ch]
print('236 decoded accesses checked; 400 randomized excitation replays passed.')
with tempfile.TemporaryDirectory(prefix='pd440-test-') as folder:
 folder=pathlib.Path(folder)
 # Independent changes to both clocks, card labels, and ID values.
 rename={0:91,1:12,2:7,3:400}
 with (folder/'bus.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['t_us','cs','op','addr','data'])
  for t,cs,op,addr,data in bus:
   if addr==0: data=0x53AA
   w.writerow([t*3+1000000000,rename[cs],op,hex(addr),hex(data)])
 with (folder/'strain.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['t_us','adc'])
  for row in csv.DictReader(open('/app/captures/site_a/strain.csv')):
   w.writerow([int(row['t_us'])*7-900000000,3*int(row['adc'])+600])
 for n in (1,2):
  subprocess.run(['python3','/app/driver.py','decode','--capture',str(folder/'bus.csv'),'--strain',str(folder/'strain.csv'),'--out',str(folder/('out%d.jsonl'%n))],check=True)
 assert (folder/'out1.jsonl').read_bytes()==(folder/'out2.jsonl').read_bytes()
 for orig,modified in zip(rows,map(json.loads,(folder/'out1.jsonl').read_text().splitlines())):
  assert modified['revision']==orig['revision'] and modified['cs']==rename[orig['cs']]
  assert modified['t_us']==orig['t_us']*3+1000000000
 # No gain discriminator: fail instead of guessing from IDs or chip-select.
 times,values=d.read_strain('/app/captures/site_a/strain.csv')
 changed=[(t,cs,op,addr,0 if addr in (9,12) else data) for t,cs,op,addr,data in bus]
 try:d.identify_revisions(changed,times,values)
 except ValueError:pass
 else:raise AssertionError('unsupported evidence was accepted')
print('Independent clock shifts/scales, ADC offset/scale, relabeled chip selects, identical IDs, deterministic output, and ambiguous-evidence rejection passed.')
print('Revisions:',dict(sorted({r['cs']:r['revision'] for r in rows}.items())))
print('Example writes:',open('/tmp/pd440-writes.json').read().strip())
PY","max_output_tokens":3000}));

